  window.finishSession=async()=>{let score=3,note='',answers={};if(activeSkill.id==='listening'||activeSkill.id==='reading'){const result=window.checkAnswers(activeSkill.id);score=result.answered?Math.max(1,Math.min(5,Math.round((result.correct/result.answered)*5))):3;answers=Object.fromEntries([...app.querySelectorAll('.question[data-q]')].map(q=>[q.dataset.q,q.querySelector('.option.selected')?.dataset.option||'']));note=result.correct+'/'+result.answered+' câu đúng'+(document.getElementById('note-'+activeSkill.id)?.value?' · '+document.getElementById('note-'+activeSkill.id).value:'')}else{const rates=[...app.querySelectorAll('.rate')].map(x=>Number(x.value));score=Math.round(rates.reduce((a,b)=>a+b,0)/rates.length);note=document.getElementById('note-'+activeSkill.id)?.value||'';if(activeSkill.id==='writing')note=(document.getElementById('writing-answer')?.value||'').trim().split(/\s+/).filter(Boolean).length+' từ'+(note?' · '+note:'')}const answerText=activeSkill.id==='writing'?document.getElementById('writing-answer')?.value||'':activeSkill.id==='speaking'?document.getElementById('speaking-notes')?.value||'':'';if(data.sessions.some(s=>s.date===today)){showToast('Buổi hôm nay đã lưu trước đó.');return}const session={date:today,skill:activeSkill.id,score,note,answers,answerText};data.sessions.push(session);data.sessions.sort((a,b)=>a.date.localeCompare(b.date));save();showToast('Đã lưu buổi học. GPT-6 Luna đang đánh giá...');await assessSession(session);setPage('progress')};
